"use client";

import React, { useState, useEffect, useCallback } from "react";
import DancingBanana from "@/components/DancingBanana";

export default function Home() {
  const [bpm, setBpm] = useState(0);
  const [taps, setTaps] = useState<number[]>([]);
  const [lastTapTime, setLastTapTime] = useState<number | null>(null);
  const [bananaCount, setBananaCount] = useState(1);
  const [selectedEmoji, setSelectedEmoji] = useState("🍌");
  const [showTip, setShowTip] = useState(true);

  const emojiOptions = [
    "🍌", "🍎", "🍊", "🍋", "🍇", "🍓", "🍑", "🍒", "🥑", "🥕", "🌽", "🥦", "🍆", "🌶️", "🥒", "🍅"
  ];

  const calculateBpm = useCallback((tapTimestamps: number[]) => {
    if (tapTimestamps.length < 2) return 0;

    // Use last 8 taps for calculation
    const recentTaps = tapTimestamps.slice(-8);
    
    // Calculate intervals between taps
    const intervals: number[] = [];
    for (let i = 1; i < recentTaps.length; i++) {
      intervals.push(recentTaps[i] - recentTaps[i - 1]);
    }

    // Average interval in ms
    const avgInterval = intervals.reduce((a, b) => a + b, 0) / intervals.length;
    
    // Convert to BPM (ms to minutes)
    const calculatedBpm = Math.round(60000 / avgInterval);
    
    // Clamp to reasonable range
    return Math.min(Math.max(calculatedBpm, 30), 300);
  }, []);

  const handleTap = useCallback(() => {
    const now = Date.now();
    
    // Reset if more than 2 seconds since last tap
    if (lastTapTime && now - lastTapTime > 2000) {
      setTaps([now]);
      setLastTapTime(now);
      setBpm(0);
      return;
    }

    const newTaps = [...taps, now];
    setTaps(newTaps);
    setLastTapTime(now);
    setBpm(calculateBpm(newTaps));
  }, [taps, lastTapTime, calculateBpm]);

  const handleReset = useCallback(() => {
    setTaps([]);
    setLastTapTime(null);
    setBpm(0);
  }, []);

  const handleAddBananas = useCallback(() => {
    setBananaCount((prev) => prev + 2);
  }, []);

  const handleRemoveBananas = useCallback(() => {
    setBananaCount((prev) => Math.max(1, prev - 2));
  }, []);

  const handleNextEmoji = useCallback(() => {
    setSelectedEmoji((prev) => {
      const currentIndex = emojiOptions.indexOf(prev);
      const nextIndex = (currentIndex + 1) % emojiOptions.length;
      return emojiOptions[nextIndex];
    });
  }, [emojiOptions]);

  const handlePrevEmoji = useCallback(() => {
    setSelectedEmoji((prev) => {
      const currentIndex = emojiOptions.indexOf(prev);
      const prevIndex = (currentIndex - 1 + emojiOptions.length) % emojiOptions.length;
      return emojiOptions[prevIndex];
    });
  }, [emojiOptions]);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.code === "Space" && !e.repeat) {
        e.preventDefault();
        handleTap();
      }
      if (e.code === "ArrowUp" && !e.repeat) {
        e.preventDefault();
        handleAddBananas();
      }
      if (e.code === "ArrowDown" && !e.repeat) {
        e.preventDefault();
        handleRemoveBananas();
      }
      if (e.code === "ArrowRight" && !e.repeat) {
        e.preventDefault();
        handleNextEmoji();
      }
      if (e.code === "ArrowLeft" && !e.repeat) {
        e.preventDefault();
        handlePrevEmoji();
      }
    };

    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, [handleTap, handleAddBananas, handleRemoveBananas, handleNextEmoji, handlePrevEmoji]);

  return (
    <div className="fixed inset-0 flex flex-col items-center justify-center bg-gradient-to-br from-zinc-950 via-purple-950/20 to-zinc-950 overflow-hidden">
      {/* Background Glow */}
      <div className="absolute inset-0 bg-[radial-gradient(circle_at_50%_50%,rgba(250,204,21,0.08),transparent_50%)]" />
      
      {/* Tip Banner */}
      {showTip && (
        <div className="absolute top-4 left-1/2 -translate-x-1/2 z-30 flex items-center gap-4 rounded-full bg-yellow-400/10 border border-yellow-400/20 px-6 py-3 backdrop-blur-sm">
          <span className="text-sm text-yellow-200">
            🎵 Put on a good song and tap <kbd className="px-1.5 py-0.5 rounded bg-white/10 text-yellow-100 font-mono text-xs">space</kbd> to the beat. Change dancers with the arrow keys.
          </span>
          <button
            onClick={() => setShowTip(false)}
            className="text-yellow-400/60 hover:text-yellow-200 transition-colors text-lg leading-none"
            aria-label="Dismiss tip"
          >
            ×
          </button>
        </div>
      )}
      
      {/* Header */}
      <header className="absolute top-8 left-8 z-20">
        <h1 className="text-3xl font-black tracking-tighter text-white">
          Emoji Dance Party
        </h1>
        <p className="text-xs text-zinc-500 uppercase tracking-widest mt-1">
          BPM Rhythm Visualizer
        </p>
        
        {/* Emoji Picker */}
        <div className="mt-4 flex flex-wrap gap-2 max-w-xs">
          {emojiOptions.map((emoji) => (
            <button
              key={emoji}
              onClick={() => setSelectedEmoji(emoji)}
              className={`text-2xl p-1 rounded-lg transition-all hover:scale-125 ${
                selectedEmoji === emoji 
                  ? "bg-white/20 ring-2 ring-yellow-400" 
                  : "hover:bg-white/10"
              }`}
            >
              {emoji}
            </button>
          ))}
        </div>
      </header>

      {/* Main Content */}
      <div className="relative z-10 flex flex-col items-center gap-12">
        {/* Dancing Emojis */}
        {bananaCount <= 5 ? (
          <div key={`${bananaCount}-${selectedEmoji}`} className="flex flex-wrap items-center justify-center gap-4">
            {Array.from({ length: bananaCount }).map((_, i) => (
              <DancingBanana key={i} bpm={bpm} emoji={selectedEmoji} />
            ))}
          </div>
        ) : (
          <div key={`${bananaCount}-${selectedEmoji}`} className="fixed inset-0 pointer-events-none">
            {Array.from({ length: bananaCount }).map((_, i) => {
              // Seeded pseudo-random positions and sizes based on index
              // Using different primes and golden ratio for better distribution
              const goldenRatio = 0.618033988749;
              const x = ((i * goldenRatio * 100) % 80) + 10; // 10-90% from left
              const y = (((i * 1337 + 42) * 13) % 60) + 20; // 20-80% from top  
              const size = 80 + (((i * 2749 + 17) * 3) % 120); // 80-200px
              return (
                <div
                  key={i}
                  className="absolute"
                  style={{
                    left: `${x}%`,
                    top: `${y}%`,
                    transform: "translate(-50%, -50%)",
                  }}
                >
                  <DancingBanana bpm={bpm} emoji={selectedEmoji} size={size} />
                </div>
              );
            })}
          </div>
        )}

        {/* BPM Display */}
        <div className="text-center">
          <div className="text-8xl font-black tracking-tighter text-white tabular-nums">
            {bpm || "—"}
          </div>
          <div className="text-xs font-bold text-zinc-500 uppercase tracking-[0.3em] mt-2">
            Beats Per Minute
          </div>
        </div>

        {/* Tap Indicator */}
        <div className="flex flex-col items-center gap-4">
          <button
            onClick={handleTap}
            className="group relative px-12 py-4 rounded-full bg-white/5 border border-white/10 text-white font-bold uppercase tracking-widest text-sm transition-all hover:bg-white/10 hover:scale-105 active:scale-95 focus:outline-none focus:ring-2 focus:ring-yellow-400/50"
          >
            <span className="relative z-10">Tap Space</span>
            <div className="absolute inset-0 rounded-full bg-yellow-400/20 opacity-0 group-active:opacity-100 transition-opacity" />
          </button>
          
          <div className="flex items-center gap-4">
            <span className="text-[10px] text-zinc-600 uppercase tracking-wider">
              {taps.length} taps recorded
            </span>
            {taps.length > 0 && (
              <button
                onClick={handleReset}
                className="text-[10px] text-zinc-500 uppercase tracking-wider hover:text-white transition-colors"
              >
                Reset
              </button>
            )}
          </div>
        </div>
      </div>

      {/* Mobile Controls */}
      <div className="absolute bottom-8 left-1/2 -translate-x-1/2 flex flex-col items-center gap-4">
        {/* Arrow Controls */}
        <div className="flex items-center gap-2">
          {/* Left Arrow - Previous Emoji */}
          <button
            onClick={handlePrevEmoji}
            className="w-12 h-12 rounded-full bg-white/5 border border-white/10 text-white text-xl flex items-center justify-center hover:bg-white/10 active:scale-95 transition-all"
            aria-label="Previous emoji"
          >
            ←
          </button>
          
          {/* Up/Down Arrows */}
          <div className="flex flex-col gap-1">
            <button
              onClick={handleAddBananas}
              className="w-12 h-8 rounded-lg bg-white/5 border border-white/10 text-white text-sm flex items-center justify-center hover:bg-white/10 active:scale-95 transition-all"
              aria-label="Add dancers"
            >
              ↑
            </button>
            <button
              onClick={handleRemoveBananas}
              className="w-12 h-8 rounded-lg bg-white/5 border border-white/10 text-white text-sm flex items-center justify-center hover:bg-white/10 active:scale-95 transition-all"
              aria-label="Remove dancers"
            >
              ↓
            </button>
          </div>
          
          {/* Right Arrow - Next Emoji */}
          <button
            onClick={handleNextEmoji}
            className="w-12 h-12 rounded-full bg-white/5 border border-white/10 text-white text-xl flex items-center justify-center hover:bg-white/10 active:scale-95 transition-all"
            aria-label="Next emoji"
          >
            →
          </button>
        </div>
        
        {/* Keyboard hint for desktop */}
        <p className="text-[10px] text-zinc-600 font-medium uppercase tracking-widest hidden md:block">
          Or use <kbd className="px-1.5 py-0.5 rounded bg-white/5 border border-white/10 text-zinc-400">SPACE</kbd> and arrow keys
        </p>
      </div>
    </div>
  );
}
